<?php use function KB\{e,url,post}; use KB\Security; ?><section class="auth-card panel"><span class="eyebrow">A FRESH START</span><h1>Let’s get you back in.</h1><p class="muted">Enter your email. We’ll queue a secure, single-use link if an active account matches.</p><?php if($error): ?><div class="notice error"><?= e($error) ?></div><?php endif; ?><?php if($notice): ?><div class="notice success" role="status"><?= e($notice) ?></div><?php endif; ?><form class="stack" method="post"><?= Security::csrfField() ?><label>Email address<input type="email" name="email" required autocomplete="email" value="<?= e(post('email')) ?>"></label><button class="button full">Send reset link</button></form><p class="form-footer"><a href="<?= e(url('login')) ?>">Back to sign in</a></p></section>
